-- MySQL: run this in a NEW test database (see README.md).
-- This creates a new table; it does not migrate an existing Users table.
CREATE TABLE Users (
    UserID INT PRIMARY KEY AUTO_INCREMENT,
    Username VARCHAR(30) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
    -- Store only the salted password hash generated by PasswordHasher in C#.
    PasswordHash VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL
);
